// Hand-authored, not generated by mdatagen, so it survives regeneration.
package metadata

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"go.uber.org/zap"
	"go.uber.org/zap/zaptest/observer"

	"go.opentelemetry.io/collector/confmap"
	"go.opentelemetry.io/collector/scraper/scrapertest"
)

func TestIndependentValueMetricConfigUnmarshal(t *testing.T) {
	t.Run("legacy", func(t *testing.T) {
		var cfg SystemMemoryLimitUtilizationMetricConfig
		require.NoError(t, cfg.Unmarshal(nil))
		require.Error(t, cfg.Unmarshal(confmap.NewFromStringMap(map[string]any{"enabled": "not-a-bool"})))
		require.NoError(t, cfg.Unmarshal(confmap.NewFromStringMap(map[string]any{"enabled": true})))
		assert.True(t, cfg.Enabled)
		assert.True(t, cfg.enabledSetByUser)
	})
	t.Run("target", func(t *testing.T) {
		var cfg SystemMemoryLimitUtilizationV1MetricConfig
		require.NoError(t, cfg.Unmarshal(nil))
		require.Error(t, cfg.Unmarshal(confmap.NewFromStringMap(map[string]any{"enabled": "not-a-bool"})))
		require.NoError(t, cfg.Unmarshal(confmap.NewFromStringMap(map[string]any{"enabled": true})))
		assert.True(t, cfg.Enabled)
		assert.True(t, cfg.enabledSetByUser)
	})
}

// TestIndependentValueTargetFollowsLegacy checks that the migration target is enabled
// when the legacy metric is enabled, the enable_new gate is on and the user did not
// configure the target explicitly.
func TestIndependentValueTargetFollowsLegacy(t *testing.T) {
	if !setFeatureGateForTest(t, ScraperSamplemigrationEmitV1SystemConventionsFeatureGate, true) {
		t.Skip("feature gate stage does not allow enabling it")
	}
	mbc := NewDefaultMetricsBuilderConfig()
	mbc.Metrics.SystemMemoryLimitUtilization.Enabled = true

	mb := NewMetricsBuilder(mbc, scrapertest.NewNopSettings(scrapertest.NopType))
	assert.True(t, mb.metricSystemMemoryLimitUtilizationV1.config.Enabled)
}

// TestEmittedNameConfigKeyInWarnings checks that user-facing warnings name the
// migration target by its config key (emitted name), without the @vN suffix.
func TestEmittedNameConfigKeyInWarnings(t *testing.T) {
	observedZapCore, observedLogs := observer.New(zap.WarnLevel)
	settings := scrapertest.NewNopSettings(scrapertest.NopType)
	settings.Logger = zap.New(observedZapCore)

	mbc := NewDefaultMetricsBuilderConfig()
	mbc.Metrics.SystemMemoryLimitUtilizationV1.enabledSetByUser = true
	NewMetricsBuilder(mbc, settings)

	logs := observedLogs.FilterMessageSnippet("should not be configured").All()
	require.Len(t, logs, 1)
	assert.Contains(t, logs[0].Message, "`system.memory.limit.utilization`")
	assert.NotContains(t, logs[0].Message, "@v1")
}
